DO $document_workspaces$ BEGIN
 IF to_regclass('public.platform_users') IS NULL OR to_regclass('public.platform_tenants') IS NULL THEN RETURN; END IF;
 CREATE TABLE platform_document_workspaces(id UUID PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,scope_type VARCHAR(20) NOT NULL,scope_id VARCHAR(64) NOT NULL,owner_id VARCHAR(36) NOT NULL,name VARCHAR(120) NOT NULL,object_namespace VARCHAR(200) NOT NULL,maximum_files BIGINT NOT NULL,maximum_bytes BIGINT NOT NULL,file_count BIGINT NOT NULL DEFAULT 0,byte_count BIGINT NOT NULL DEFAULT 0,state VARCHAR(16) NOT NULL,revision BIGINT NOT NULL,create_idempotency_key VARCHAR(200) NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,archived_at TIMESTAMPTZ,CONSTRAINT fk_document_workspace_tenant FOREIGN KEY(tenant_id) REFERENCES platform_tenants(id),CONSTRAINT fk_document_workspace_owner FOREIGN KEY(owner_id) REFERENCES platform_users(id),CONSTRAINT uk_document_workspace_scope UNIQUE(id,tenant_id),CONSTRAINT uk_document_workspace_namespace UNIQUE(object_namespace),CONSTRAINT uk_document_workspace_create UNIQUE(tenant_id,owner_id,create_idempotency_key),CONSTRAINT ck_document_workspace_scope CHECK((scope_type='USER' AND scope_id=owner_id) OR (scope_type='ORGANIZATION' AND scope_id=tenant_id)),CONSTRAINT ck_document_workspace_namespace CHECK(object_namespace=('document-workspace:'||id::text)),CONSTRAINT ck_document_workspace_quota CHECK(maximum_files BETWEEN 1 AND 10000 AND maximum_bytes BETWEEN 1048576 AND 1073741824 AND file_count BETWEEN 0 AND maximum_files AND byte_count BETWEEN 0 AND maximum_bytes),CONSTRAINT ck_document_workspace_state CHECK(state IN('ACTIVE','PAUSED','ARCHIVED') AND revision>0 AND ((state='ARCHIVED' AND archived_at IS NOT NULL) OR (state<>'ARCHIVED' AND archived_at IS NULL))));
 CREATE TABLE platform_document_workspace_files(workspace_id UUID NOT NULL,tenant_id VARCHAR(64) NOT NULL,path VARCHAR(500) NOT NULL,byte_size BIGINT NOT NULL,content_hash VARCHAR(71) NOT NULL,updated_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(workspace_id,path),CONSTRAINT fk_document_workspace_file_scope FOREIGN KEY(workspace_id,tenant_id) REFERENCES platform_document_workspaces(id,tenant_id) ON DELETE CASCADE,CONSTRAINT ck_document_workspace_file CHECK(path<>'' AND path!~'^/' AND path!~'(^|/)\.\.(/|$)' AND byte_size BETWEEN 0 AND 500000 AND content_hash~'^sha256:[0-9a-f]{64}$'));
 CREATE TABLE platform_document_workspace_operations(id UUID PRIMARY KEY,tenant_id VARCHAR(64) NOT NULL,workspace_id UUID NOT NULL,actor_user_id VARCHAR(36) NOT NULL,tool_call_id VARCHAR(200) NOT NULL,idempotency_key VARCHAR(200) NOT NULL,input_hash VARCHAR(71) NOT NULL,operation_type VARCHAR(16) NOT NULL,path VARCHAR(500) NOT NULL,requested_bytes BIGINT NOT NULL,previous_bytes BIGINT NOT NULL,previous_file_present BOOLEAN NOT NULL,reserved_files BIGINT NOT NULL,reserved_bytes BIGINT NOT NULL,state VARCHAR(16) NOT NULL,result_bytes BIGINT,result_hash VARCHAR(71),safe_error_code VARCHAR(120),revision BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,completed_at TIMESTAMPTZ,CONSTRAINT fk_document_workspace_operation_scope FOREIGN KEY(workspace_id,tenant_id) REFERENCES platform_document_workspaces(id,tenant_id) ON DELETE CASCADE,CONSTRAINT fk_document_workspace_operation_actor FOREIGN KEY(actor_user_id) REFERENCES platform_users(id),CONSTRAINT uk_document_workspace_tool_call UNIQUE(workspace_id,tool_call_id),CONSTRAINT uk_document_workspace_idempotency UNIQUE(workspace_id,idempotency_key),CONSTRAINT ck_document_workspace_operation_hash CHECK(input_hash~'^sha256:[0-9a-f]{64}$' AND (result_hash IS NULL OR result_hash~'^sha256:[0-9a-f]{64}$')),CONSTRAINT ck_document_workspace_operation_state CHECK(operation_type IN('WRITE','DELETE') AND state IN('PENDING','UNKNOWN','SUCCEEDED','FAILED') AND revision>0 AND requested_bytes BETWEEN 0 AND 500000 AND previous_bytes BETWEEN 0 AND 500000 AND reserved_files BETWEEN 0 AND 1 AND reserved_bytes BETWEEN 0 AND 500000 AND ((state IN('SUCCEEDED','FAILED') AND completed_at IS NOT NULL) OR (state IN('PENDING','UNKNOWN') AND completed_at IS NULL))));
 CREATE UNIQUE INDEX uk_document_workspace_active_path ON platform_document_workspace_operations(workspace_id,path) WHERE state IN('PENDING','UNKNOWN');
END $document_workspaces$;
